#!/usr/bin/env bash
# Generates the i3 colour snippet from palette.sh
DIR="$(cd "$(dirname "$(readlink -f "$0")")" && pwd)"
. "$DIR/palette.sh"
cat > "$DIR/i3-cyberneon.conf" <<CONF
# Generated by apply.sh from palette.sh. Do not edit by hand.
default_border pixel 2
default_floating_border pixel 2
gaps inner 8
gaps outer 2
#                       border      background  text        indicator   child_border
client.focused          #$CN_PINK   #$CN_BG     #$CN_TEXT   #$CN_CYAN   #$CN_PINK
client.focused_inactive #$CN_CYAN   #$CN_BG     #$CN_MUTED  #$CN_BG2    #$CN_BG2
client.unfocused        #$CN_BG2    #$CN_BG     #$CN_MUTED  #$CN_BG2    #$CN_BG2
client.urgent           #$CN_YELLOW #$CN_BG     #$CN_YELLOW #$CN_YELLOW #$CN_YELLOW
client.placeholder      #$CN_BG2    #$CN_BG     #$CN_MUTED  #$CN_BG2    #$CN_BG2
client.background       #$CN_BG
exec_always --no-startup-id $DIR/wallpaper.sh
exec_always --no-startup-id sh -c 'pkill -x dunst; sleep 0.3; dunst'
CONF
echo "wrote $DIR/i3-cyberneon.conf"

# polybar + rofi from templates
gen() { sed -e "s/@BG@/$CN_BG/g" -e "s/@BG2@/$CN_BG2/g" -e "s/@PINK@/$CN_PINK/g" -e "s/@CYAN@/$CN_CYAN/g" \
            -e "s/@YELLOW@/$CN_YELLOW/g" -e "s/@TEXT@/$CN_TEXT/g" -e "s/@MUTED@/$CN_MUTED/g" -e "s/@GREEN@/$CN_GREEN/g" -e "s/@PURPLE@/$CN_PURPLE/g" -e "s/@BLUE@/$CN_BLUE/g" -e "s/@BLACK@/$CN_BLACK/g" -e "s/@FONT@/$CN_FONT/g" "$1" > "$2"; }
gen "$DIR/templates/polybar.ini.in" "$DIR/polybar.ini"
gen "$DIR/templates/rofi.rasi.in"   "$DIR/rofi-cyberneon.rasi"
gen "$DIR/templates/dunstrc.in"            "$DIR/dunstrc"
gen "$DIR/templates/kitty.conf.in"         "$DIR/kitty-cyberneon.conf"
gen "$DIR/templates/alacritty-colors.toml.in" "$DIR/alacritty-cyberneon.toml"
cp "$DIR/templates/launch.sh" "$DIR/polybar-launch.sh"; chmod +x "$DIR/polybar-launch.sh"
echo "wrote polybar, rofi, dunst, kitty and alacritty files"
